import React, { useEffect, useState, useRef } from "react";

export default function DocSectionNav({ items }) {
  const [activeId, setActiveId] = useState(null);
  const navRef = useRef(null);
  const activeItemRef = useRef(null);

  useEffect(() => {
    // Read top bar height from CSS custom property if present
    const computed = getComputedStyle(document.body);
    const rawTopBar = (computed.getPropertyValue("--uls-top-bar-height") || "").trim();

    // Ensure value is in pixels for IntersectionObserver (only px or % allowed)
    const resolveToPx = (value) => {
      if (!value) return 64; // default px
      if (value.endsWith("px")) return parseFloat(value) || 64;
      if (value.endsWith("%")) return 64; // avoid %, use default
      // Try to resolve other units (e.g., rem) by measuring
      const tmp = document.createElement("div");
      tmp.style.position = "absolute";
      tmp.style.visibility = "hidden";
      tmp.style.height = value;
      document.body.appendChild(tmp);
      const px = tmp.getBoundingClientRect().height || 64;
      document.body.removeChild(tmp);
      return px;
    };

    const topBarPx = resolveToPx(rawTopBar);

    // Use negative top margin so intersection triggers after clearing the fixed header
    const observerOptions = {
      root: null,
      rootMargin: `-${topBarPx}px 0px 0px 0px`,
      threshold: 0,
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          setActiveId(entry.target.id);
        }
      });
    }, observerOptions);

    items.forEach((item) => {
      const section = document.getElementById(item.id);
      if (section) observer.observe(section);
    });

    return () => observer.disconnect();
  }, [items]);

  // Auto-scroll navigation to show active item
  useEffect(() => {
    if (activeItemRef.current && navRef.current) {
      const nav = navRef.current;
      const activeItem = activeItemRef.current;
      
      const navRect = nav.getBoundingClientRect();
      const itemRect = activeItem.getBoundingClientRect();
      
      // Calculate if item is visible in nav
      const isVisible = itemRect.top >= navRect.top && itemRect.bottom <= navRect.bottom;
      
      if (!isVisible) {
        // Scroll to center the active item
        const scrollTop = activeItem.offsetTop - (nav.clientHeight / 2) + (activeItem.clientHeight / 2);
        nav.scrollTo({
          top: scrollTop,
          behavior: 'smooth'
        });
      }
    }
  }, [activeId]);

  const handleScroll = (id) => {
    const section = document.getElementById(id);
    if (!section) return;

    // Smooth scroll accounting for fixed top bar height
    const computed = getComputedStyle(document.body);
    const topBar = computed.getPropertyValue("--uls-top-bar-height").trim() || "64px";
    const topBarPx = parseInt(topBar, 10) || 64;
    const top = section.getBoundingClientRect().top + window.pageYOffset - topBarPx - 8; // extra offset

    window.scrollTo({ top, behavior: "smooth" });
  };

  return (
    <nav className="doc-section-nav" ref={navRef}>
      <ul>
        {items.map((item) => (
          <li key={item.id}>
            <button
              ref={activeId === item.id ? activeItemRef : null}
              className={`doc-section-nav-item pdx12 pdy4 bdr-l2 font-size12 whitespace-nowrap  ${
                activeId === item.id ? "active bdr-primary fg-primary" : ""
              }`}
              onClick={() => handleScroll(item.id)}
            >
              {item.sectionNav}
            </button>
          </li>
        ))}
      </ul>
    </nav>
  );
}